#include <cmath>
#include <vector>
#include <iostream>

class vec3 {
public:
    double x, y, z;

    vec3() : x(0), y(0), z(0) {}
    vec3(double x, double y, double z) : x(x), y(y), z(z) {}

    vec3 operator+(const vec3& v) const { return vec3(x + v.x, y + v.y, z + v.z); }
    vec3 operator-(const vec3& v) const { return vec3(x - v.x, y - v.y, z - v.z); }
    vec3 operator*(double s) const { return vec3(x * s, y * s, z * s); }
    vec3 operator/(double s) const { return vec3(x / s, y / s, z / s); }

    vec3& operator+=(const vec3& v) { x += v.x; y += v.y; z += v.z; return *this; }
    vec3& operator-=(const vec3& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
    vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
    vec3& operator/=(double s) { x /= s; y /= s; z /= s; return *this; }
};

inline vec3 operator*(double s, const vec3& v) { return v * s; }

// Function to implement
void velocityVerletStep1(vec3& pos, vec3& vel, const vec3& force, double mass, double dt) {
    // Calculate acceleration from force: a = F / m
    vec3 acc = force / mass;

    // Update velocity by half timestep: v(t + dt/2) = v(t) + a * (dt/2)
    vel += acc * (dt * 0.5);

    // Update position using the new (half-step) velocity: x(t + dt) = x(t) + v(t + dt/2) * dt
    pos += vel * dt;
}

// Test the implementation
int main() {
    // Test case: particle with initial position (0,0,0), velocity (1,0,0)
    // Force = (2,0,0), mass = 1, dt = 0.1
    // Expected: acc = (2,0,0), vel after half step = (1,0,0) + (2,0,0) * 0.05 = (1.1, 0, 0)
    // pos after full step = (0,0,0) + (1.1,0,0) * 0.1 = (0.11, 0, 0)

    vec3 pos(0, 0, 0);
    vec3 vel(1, 0, 0);
    vec3 force(2, 0, 0);
    double mass = 1.0;
    double dt = 0.1;

    velocityVerletStep1(pos, vel, force, mass, dt);

    // Check results
    bool pass = true;
    if (std::abs(pos.x - 0.11) > 1e-10) { std::cout << "FAIL pos.x: " << pos.x << std::endl; pass = false; }
    if (std::abs(vel.x - 1.1) > 1e-10) { std::cout << "FAIL vel.x: " << vel.x << std::endl; pass = false; }
    if (std::abs(pos.y) > 1e-10 || std::abs(pos.z) > 1e-10) { std::cout << "FAIL pos.y/z" << std::endl; pass = false; }
    if (std::abs(vel.y) > 1e-10 || std::abs(vel.z) > 1e-10) { std::cout << "FAIL vel.y/z" << std::endl; pass = false; }

    if (pass) {
        std::cout << "PASS: pos=(" << pos.x << "," << pos.y << "," << pos.z << ") vel=(" << vel.x << "," << vel.y << "," << vel.z << ")" << std::endl;
    }

    return pass ? 0 : 1;
}

